"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { countWords, score, type Score } from "@/lib/writing-score";
import type { WritingTask } from "@/lib/writing";

/**
 * Where a student actually writes.
 *
 * The clock is the point. A student who can write 250 good words in an hour and
 * cannot write them in forty does not have a writing problem, they have a
 * timing problem, and the only way to find that out is to be timed. So the
 * timer starts on the first keystroke rather than on page load — no penalty for
 * reading the question properly — and it never locks the box when it runs out.
 * Being cut off mid-sentence teaches nothing; seeing "you were 80 words short
 * when the time went" teaches the whole lesson.
 *
 * The draft is saved as it is typed. A student on a phone who takes a call
 * forty minutes into an essay should not lose it.
 */

const fmt = (s: number) =>
  `${Math.floor(Math.abs(s) / 60)}:${String(Math.abs(s) % 60).padStart(2, "0")}`;

export default function WritingDesk({ task, start }: { task: WritingTask; start?: number }) {
  const store = `pec_writing_${task.id}`;
  /* Opened from an essay-type list on one question: that question is the one
     on screen, even if an older draft of this topic was on another. */
  const [chosen, setChosen] = useState(start ?? 0);
  const [text, setText] = useState("");
  const [left, setLeft] = useState(task.minutes * 60);
  const [running, setRunning] = useState(false);
  const [done, setDone] = useState<Score | null>(null);
  const [showIdeas, setShowIdeas] = useState(false);
  const [showChart, setShowChart] = useState(false);
  /* The saved copy in the student's account. Pressing "Check again" before
     the teacher has marked it updates the same copy rather than adding one. */
  const savedId = useRef<string | undefined>(undefined);
  const router = useRouter();
  const [saved, setSaved] = useState<"" | "saving" | "saved" | "failed" | "off" | "setup">("");
  const [saveWhy, setSaveWhy] = useState("");
  const [elapsedAtFinish, setElapsedAtFinish] = useState(0);
  const box = useRef<HTMLTextAreaElement>(null);

  /* bring back an unfinished draft. A draft on a different question of this
     topic is left in storage, untouched, until the student starts writing. */
  const keep = useRef(true);
  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(store);
      if (raw) {
        const d = JSON.parse(raw);
        if (start !== undefined && typeof d.chosen === "number" && d.chosen !== start) { keep.current = false; return; }
        if (typeof d.text === "string") setText(d.text);
        if (typeof d.left === "number") setLeft(d.left);
        if (typeof d.chosen === "number") setChosen(d.chosen);
      }
    } catch { /* a blocked store is not a reason to fail */ }
  }, [store, start]);

  useEffect(() => {
    if (!keep.current) { if (!text) return; keep.current = true; }
    try { window.localStorage.setItem(store, JSON.stringify({ text, left, chosen })); }
    catch { /* nothing to do */ }
  }, [store, text, left, chosen]);

  useEffect(() => {
    if (!running) return;
    const t = setInterval(() => setLeft((s) => s - 1), 1000);
    return () => clearInterval(t);
  }, [running]);

  const live = useMemo(() => countWords(text), [text]);
  const short = live < task.minWords;

  const finish = useCallback(() => {
    setRunning(false);
    const used = task.minutes * 60 - left;
    setElapsedAtFinish(used);
    const result = score(text, task.minWords, task.kind, task.check);
    setDone(result);
    window.scrollTo({ top: 0, behavior: "smooth" });

    setSaved("saving");
    fetch("/api/practice/writing", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: savedId.current, task_id: task.id, chosen, body: text,
        seconds: used, estimate: result.estimate,
      }),
    })
      .then((r) => r.json().catch(() => ({})))
      .then((d) => {
        // refresh re-reads the "saved answers" list under the question
        // without touching anything typed on this page
        if (d.saved) { savedId.current = d.id; setSaved("saved"); router.refresh(); }
        else {
          setSaveWhy([d.reason, d.detail, d.v].filter(Boolean).join(" · ") || "no answer from the server");
          setSaved(d.reason === "not a student" ? "off" : d.reason === "table missing" || d.reason === "database not set up" ? "setup" : "failed");
        }
      })
      .catch(() => { setSaveWhy("no connection"); setSaved("failed"); });
  }, [text, task, left, chosen, router]);

  const restart = () => {
    setDone(null); setText(""); setLeft(task.minutes * 60); setRunning(false);
    savedId.current = undefined; setSaved("");
    try { window.localStorage.removeItem(store); } catch { /* fine */ }
    box.current?.focus();
  };

  const prompt = task.prompts?.[chosen];
  const split = task.kind === "task1" && !!task.images?.length;

  return (
    <div className="wr-desk">
      <div className="wr-head">
          <div>
            <span className="wr-kind">{task.kind === "task1" ? `Writing Task 1 · Academic${task.chartType ? ` · ${task.chartType}` : ""}` : task.kind === "gt1" ? `Writing Task 1 · GT letter${task.register ? ` · ${task.register}` : ""}` : "Writing Task 2"}</span>
            {!split && <h1>{task.title}</h1>}
          </div>
          <span className={"wr-clock" + (left < 0 ? " over" : left < 300 ? " low" : "")}>
            {left < 0 ? "+" : ""}{fmt(left)}
            <small>{running ? "writing" : done ? "finished" : "starts when you type"}</small>
          </span>
      </div>

      {/* ---------------------------------------------------------- feedback */}
      {/* On a phone the chart sits above the answer box and scrolls out of
          sight while the student writes, so a button brings it back. */}
      {split && (
        <button type="button" className="wr-chartbtn" onClick={() => setShowChart(true)}>View chart</button>
      )}
      {split && showChart && (
        <div className="wr-chartov" role="dialog" aria-label="The chart for this task" onClick={() => setShowChart(false)}>
          <div className="wr-chartin" onClick={(e) => e.stopPropagation()}>
            <button type="button" className="btn btn-outline" onClick={() => setShowChart(false)}>Close</button>
            {task.images!.map((src) => (
              // eslint-disable-next-line @next/next/no-img-element
              <img key={src} src={`/practice/writing/${src}`} alt="The chart for this task" />
            ))}
          </div>
        </div>
      )}

      {done && <Report done={done} elapsed={elapsedAtFinish} restart={restart} phrases={task.phrases} letter={!!task.check && task.kind === "gt1"} report={!!task.check && task.kind === "task1"} saved={saved} why={saveWhy} />}

      {/* Task 1 Academic: the chart sits beside the answer box, as it does on
          the computer-delivered test, so a student never scrolls away from the
          figures they are describing. Letters and essays keep one column. */}
      <div className={"wr-work" + (split ? " split" : "")}>
      {/* ---------------------------------------------------------- question */}
      <section className="pr-set wr-q">
        {split && <div className="wr-panel-h">Question</div>}
        {split && <h1 className="wr-qtitle">{task.title}</h1>}

        {task.images?.length ? (
          <div className="wr-figs">
            {task.images.map((src) => (
              // eslint-disable-next-line @next/next/no-img-element
              <img key={src} src={`/practice/writing/${src}`} alt="The chart for this task" />
            ))}
          </div>
        ) : null}

        {task.prompts && task.prompts.length > 1 && (
          <div className="wr-pick">
            {task.prompts.map((_, i) => (
              <button key={i} type="button"
                className={"wr-tab" + (i === chosen ? " on" : "")}
                onClick={() => setChosen(i)} disabled={running || !!done}>
                Question {i + 1}
              </button>
            ))}
          </div>
        )}

        {prompt && <blockquote className="wr-prompt">{prompt}</blockquote>}

        <p className="wr-rule">
          You should spend about <b>{task.minutes} minutes</b> on this task and write at
          least <b>{task.minWords} words</b>.
        </p>

        {task.links?.length ? (
          <p className="wr-links">
            {task.links.map((u, i) => (
              <a key={u} href={u} target="_blank" rel="noopener noreferrer">
                {/youtu\.?be/i.test(u) ? "▶ Watch the lesson" : `Read more${task.links!.length > 1 ? ` (${i + 1})` : ""}`}
              </a>
            ))}
          </p>
        ) : null}

        {task.ideas?.length ? (
          <div className="wr-ideas">
            <button type="button" className="wr-ideas-go" onClick={() => setShowIdeas((v) => !v)}>
              {showIdeas ? "Hide the idea list" : `Stuck? ${task.ideas.length} ideas for this topic`}
            </button>
            {showIdeas && (
              <>
                <p className="wr-ideas-warn">
                  These are prompts for your own thinking, not sentences to copy. An
                  examiner has read them before.
                </p>
                <ul>{task.ideas.map((x, i) => <li key={i}>{x}</li>)}</ul>
              </>
            )}
          </div>
        ) : null}
      </section>

      {/* ------------------------------------------------------------- write */}
      <section className="pr-set wr-w">
        {split && <div className="wr-panel-h">Answer sheet</div>}
        <div className="wr-bar">
          <span className={"wr-count" + (short ? " short" : " ok")}>
            {live} / {task.minWords} words
          </span>
          {left < 0 && !done && (
            <span className="wr-overtime">over time — finish the sentence and stop</span>
          )}
          <span className="grow" />
          <button type="button" className="btn btn-coral" onClick={finish} disabled={!text.trim()}>
            {done ? "Check again" : "I have finished"}
          </button>
        </div>

        <textarea
          ref={box}
          className="wr-box"
          value={text}
          placeholder="Write your answer here. Leave a blank line between paragraphs."
          onChange={(e) => { setText(e.target.value); if (!running && !done) setRunning(true); }}
          spellCheck={false}
          rows={18}
        />
        <p className="wr-saved">
          Saved on this device as you type — you can close this and come back.
          Spell-check is off, exactly as in the real test.
        </p>
      </section>
      </div>
    </div>
  );
}

function Report({ done, elapsed, restart, phrases, letter, report, saved, why }: {
  done: Score; elapsed: number; restart: () => void; phrases?: string[]; letter?: boolean; report?: boolean;
  saved?: "" | "saving" | "saved" | "failed" | "off" | "setup"; why?: string;
}) {
  return (
    <section className="pr-set wr-report">
          <h2>Your writing, checked</h2>
          {saved === "saving" && <p className="wr-savednote">Saving to your account…</p>}
          {saved === "saved" && (
            <p className="wr-savednote ok">
              ✓ Saved to your account. Your teacher will check it and mark the mistakes — it is listed
              under this question (scroll down) and in <Link href="/practice/results#writing">My results</Link>.
            </p>
          )}
          {saved === "setup" && (
            <p className="wr-savednote bad">
              Saving writing to your account is not switched on yet. Show this to Narinder Sir — and
              copy your writing somewhere safe for now.
              {why && <small style={{ display: "block", opacity: 0.7, marginTop: 4 }}>Reason: {why}</small>}
            </p>
          )}
          {saved === "failed" && (
            <p className="wr-savednote bad">
              Could not save it to your account just now. Press “Check again” in a minute, or copy your
              writing somewhere safe.
              {why && <small style={{ display: "block", opacity: 0.7, marginTop: 4 }}>Reason: {why}</small>}
            </p>
          )}
          <div className="wr-tiles">
            <div className="wr-tile"><span className="v">{done.words}</span><span className="k">words</span></div>
            <div className="wr-tile"><span className="v">{done.paragraphs}</span><span className="k">paragraphs</span></div>
            <div className="wr-tile"><span className="v">{done.avgSentence}</span><span className="k">words per sentence</span></div>
            <div className="wr-tile"><span className="v">{fmt(elapsed)}</span><span className="k">time taken</span></div>
          </div>

          <div className="wr-est">
            <b>Rough guide: band {done.estimate.toFixed(1)}</b>
            <span>
              {report
                ? "This checks length, paragraphs, the overview, the chart's key features and figures, an introduction copied from the question, spelling and common grammar slips. It cannot judge how well you describe the data, so your teacher gives the real band."
                : letter
                ? "This checks length, paragraphs, the three bullet points, the greeting and sign-off, tone, spelling and common grammar slips. It cannot judge how well you say things, so your teacher gives the real band."
                : "This counts length, structure, linking and vocabulary range. It cannot read your argument, so it is a starting point for your teacher, never a result."}
            </span>
          </div>

          <ul className="wr-notes">
            {done.notes.map((n, i) => (
              <li key={i} className={n.kind}>
                <span className="mk">{n.kind === "good" ? "✓" : "→"}</span>{n.text}
              </li>
            ))}
          </ul>

          {phrases?.length ? (
            <div className="wr-phr">
              <h3>Useful phrases for this {report ? "report" : "letter"}</h3>
              <ul>{phrases.map((x, i) => <li key={i}>{x}</li>)}</ul>
            </div>
          ) : null}

          <div className="wr-acts">
            <button type="button" className="btn btn-coral" onClick={restart}>Write it again</button>
            <Link className="btn btn-outline" href="/practice/writing">Back to the list</Link>
          </div>
        </section>
  );
}
